public class IOUtils_skip_TriageGen2Test {

    @Test
    public void testSkip_ExactMatch() throws IOException {
        byte[] data = "0123456789".getBytes();
        try (InputStream is = new ByteArrayInputStream(data)) {
            long skipped = IOUtils.skip(is, 5);
            assertEquals(5L, skipped);
            assertEquals('5', (char) is.read());
        }
    }












}

