package org.apache.commons.compress.utils;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.Closeable;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.SequenceInputStream;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.Enumeration;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class IOUtils_skip_TriageGen2Test {







    @Test
    public void testSkip_PartialSkipViaSkipMethod() throws IOException {
        // Use a custom InputStream that returns 0 for skip() to force the readFully logic
        InputStream is = new InputStream() {
            private final ByteArrayInputStream delegate = new ByteArrayInputStream("0123456789".getBytes());

            @Override
            public int read() throws IOException {
                return delegate.read();
            }

            @Override
            public long skip(long n) throws IOException {
                // Force skip to return 0 to trigger the second while loop (readFully)
                return 0;
            }

            @Override
            public int available() {
                return delegate.available();
            }
        };

        long skipped = IOUtils.skip(is, 5);
        assertEquals(5L, skipped);
    }






}

package org.apache.commons.compress.utils;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.Closeable;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.SequenceInputStream;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.Enumeration;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class IOUtils_skip_TriageGen2Test {









    @Test
    public void testSkip_LargeSkipTriggersBufferLoop() throws IOException {
        // A stream that works partially with skip() then requires reading
        InputStream is = new InputStream() {
            private final ByteArrayInputStream delegate = new ByteArrayInputStream("0123456789".getBytes());
            private int skipCount = 0;

            @Override
            public int read() throws IOException {
                return delegate.read();
            }

            @Override
            public long skip(long n) throws IOException {
                if (skipCount == 0) {
                    skipCount++;
                    return 2; // Skip only 2, then return 0 to force readFully
                }
                return 0;
            }

            @Override
            public int available() {
                return delegate.available();
            }
        };

        long skipped = IOUtils.skip(is, 5);
        assertEquals(5L, skipped);
    }




}

