    @Test
    public void testSkip_WithIOException() throws IOException {
        InputStream is = new InputStream() {
            @Override
            public int read() throws IOException {
                throw new IOException("Simulated error");
            }

            @Override
            public long skip(long n) throws IOException {
                throw new IOException("Simulated error");
            }
        };

